description:
Output from a child arrives in arbitrary chunks (lesson 1.04). Collect it into lines, one collector per stream:

```cpp
class LineCollector
{
public:
    void add(std::string_view chunk);
    void finish();
    std::vector<std::string> take();
    std::size_t pending() const;
};
```

- **add** appends a chunk. Every `\n` ends a line; a `\r` directly before it is dropped (Windows line endings), and so is a lone `\r` at the very end of a line. Lines do not include their `\n`.
- **finish** is called at end-of-file: whatever is left becomes a last line, unless nothing is left.
- **take** returns the complete lines collected so far, in order, and forgets them.
- **pending** is the number of bytes waiting for the end of their line.

A `\r\n` split across two chunks (`\r` at the end of one, `\n` at the start of the next) must still give one line ending, not a stray `\r`.

starter.solution.cpp:
#include <string>
#include <string_view>
#include <vector>

class LineCollector
{
public:
    void add(std::string_view chunk) {}
    void finish() {}
    std::vector<std::string> take() { return {}; }
    std::size_t pending() const { return 0; }
};

solution.solution.cpp:
#include <string>
#include <string_view>
#include <utility>
#include <vector>

class LineCollector
{
public:
    void add(std::string_view chunk)
    {
        for (char c : chunk)
        {
            if (c == '\n')
            {
                if (!partial.empty() && partial.back() == '\r') partial.pop_back();
                ready.push_back(std::move(partial));
                partial.clear();
            }
            else partial += c;
        }
    }

    void finish()
    {
        if (partial.empty()) return;
        if (partial.back() == '\r') partial.pop_back();
        ready.push_back(std::move(partial));
        partial.clear();
    }

    std::vector<std::string> take()
    {
        std::vector<std::string> out{ std::move(ready) };
        ready.clear();
        return out;
    }

    std::size_t pending() const { return partial.size(); }

private:
    std::string partial;
    std::vector<std::string> ready;
};

unitTests:
using S = std::vector<std::string>;
TEST("whole and partial lines") {
    LineCollector c;
    c.add("building a.cpp\r\nbuilding b");
    CHECK_EQ(c.take(), (S{ "building a.cpp" }));
    CHECK_EQ(c.pending(), 10u);
    c.add(".cpp\r\n2 files\n");
    CHECK_EQ(c.take(), (S{ "building b.cpp", "2 files" }));
    CHECK_EQ(c.pending(), 0u);
    CHECK(c.take().empty());
}
TEST("CRLF split across chunks") {
    LineCollector c;
    c.add("one\r");
    c.add("\ntwo\r");
    c.add("\n");
    CHECK_EQ(c.take(), (S{ "one", "two" }));
}
TEST("the last line at end of file") {
    LineCollector c;
    c.add("done\nexit code 0");
    c.finish();
    CHECK_EQ(c.take(), (S{ "done", "exit code 0" }));
    LineCollector empty;
    empty.add("ends cleanly\n");
    empty.finish();
    CHECK_EQ(empty.take(), (S{ "ends cleanly" }));
    LineCollector cr;
    cr.add("odd\r");
    cr.finish();
    CHECK_EQ(cr.take(), (S{ "odd" }));
}
TEST("blank lines are kept") {
    LineCollector c;
    c.add("a\n\n\r\nb\n");
    CHECK_EQ(c.take(), (S{ "a", "", "", "b" }));
}

